package main

import (
 "context"
 "os"
 "path/filepath"
 "github.com/lox/clyde/harness/memory"
 "github.com/lox/clyde/harness/planner"
)

func main() {
 dir := os.Args[1]
 s, err := memory.Open(filepath.Join(dir,"episodes.db"),filepath.Join(dir,"semantic"))
 if err != nil { panic(err) }; defer s.Close()
 cp := planner.Checkpoint{Started:true,AutoPaused:true, Recovery:&planner.RecoveryEpisode{Attempts:0,Closed:true},
 Project:&planner.Project{Summary:"Gather eight birch logs. Two are in inventory; earlier path search failed. Owner wants the original eight, not merely movement.",Request:"Gather eight birch logs.",RequestID:"historical"},
 Dialogue:[]planner.Turn{{RequestID:"historical",Speaker:"Alex",Text:"Gather eight birch logs."},{RequestID:"historical",Speaker:"Clyde",Text:"I have two logs but my recovery attempts are exhausted.",ReplyIntent:true}}}
 if err := s.Commit(context.Background(),cp,nil); err != nil {panic(err)}
}

