)
func main(){
 jc,err:=jev.FromEnv();if err!=nil{panic(err)}
 qs,err:=judge.LoadQuestions("prompts/judge.yaml");if err!=nil{panic(err)}
 j:=judge.New(judge.BodySource{URL:"http://127.0.0.1:7789"},judge.JevBackend{Client:jc},qs,judge.DefaultConfig())
