}

drivers.live-stall.go:
package main
import (
 "context"
 "encoding/json"
 "fmt"
 "os"
 "time"
 "github.com/lox/clyde/harness/body"
 "github.com/lox/clyde/harness/judge"
 "github.com/lox/clyde/harness/jev"
)
func main(){
 ctx,cancel:=context.WithTimeout(context.Background(),25*time.Second);defer cancel()
 c:=&body.Client{URL:"http://127.0.0.1:7790"}
 a,err:=c.Action(ctx,map[string]any{"type":"eval","code":"await sleep(60000)"});if err!=nil{panic(err)}
 jc,err:=jev.FromEnv();if err!=nil{panic(err)}
 qs,err:=judge.LoadQuestions("prompts/judge.yaml");if err!=nil{panic(err)}
 j:=judge.New(judge.BodySource{URL:c.URL},judge.JevBackend{Client:jc},qs,judge.DefaultConfig())
 started:=time.Now()
 enc:=json.NewEncoder(os.Stdout)
 err=j.Run(ctx,os.Stdout,func(it judge.Interrupt){
  enc.Encode(map[string]any{"interrupt":it,"elapsed":time.Since(started).Seconds()})
  if it.Reason!="stuck" {panic("unexpected interrupt "+it.Reason)}
  if it.ActionToken!=a.Token {panic("wrong observed owner")}
  stopped,e:=c.StopAction(ctx,it.ActionToken);if e!=nil||stopped==nil{panic(fmt.Sprint(stopped,e))}
  card,e:=c.State(ctx);if e!=nil||card.Action!=nil{panic("still running")}
  enc.Encode(map[string]any{"PASS":"live motionless stall stopped only observed owner","stopped":stopped})
  cancel()
 })
 if err!=nil{panic(err)}
 if time.Since(started)>24*time.Second {panic("stall never stopped")}
}

