import collections, hashlib, json, pathlib, sqlite3, subprocess

root=pathlib.Path('/home/user/workspace/repo')
scratch=pathlib.Path('/tmp/slice13')
def load(p):
    try: return json.loads(p.read_text())
    except (ValueError,FileNotFoundError): return None
def lines(p):
    if not p.exists(): return []
    out=[]
    for s in p.read_text().splitlines():
        try: out.append(json.loads(s))
        except ValueError: pass
    return out
def digest(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def status(s):
    if not isinstance(s,dict): return s
    return {k:v for k,v in s.items() if k!='params'}
def card(c):
    if not c: return c
    return {k:(status(v) if k in ['action','lastAction'] else v) for k,v in c.items()}
def judges(p):
    rows=[r for r in lines(p) if 'backend' in r]
    lat=sorted(r.get('state_ms',0) for r in rows)
    return {'ticks':len(rows),'cost_usd':sum(r.get('cost_usd',0) for r in rows),
      'returned_input_tokens':sum((r.get('usage') or {}).get('input_tokens',0) for r in rows),
      'errors':[{'ts':r.get('ts'),'error':r['error']} for r in rows if r.get('error')],
      'interrupt_counts':dict(collections.Counter((r.get('interrupt') or {}).get('reason') for r in rows)),
      'interrupts':[r['interrupt'] for r in rows if (r.get('interrupt') or {}).get('reason')!='none'],
      'state_ms_p50':lat[len(lat)//2] if lat else None,'state_ms_p95':lat[int(len(lat)*.95)] if lat else None,
      'first_card':card(rows[0].get('card')) if rows else None,
      'terminal_stuck_suppressed':sum((r.get('interrupt') or {}).get('detail','').startswith('inapplicable stuck') for r in rows)}

e={'baseline_source':'ddfb9ee6ac2ae756e1feed6c29c24fa59d70abf0',
 'settings':{'model':'gpt-6.1-sol','effort':'low','judge':'jev','max_steps':40,'max_seconds':300,'recovery_limit':2,'experiment_allowance_usd':5},
 'method':'Frozen source via git archive; fixed two repetitions of each obstruction, one each of 12 unchanged controls and two negative fixtures. Real chat uses the slice11 driver with only ports/paths changed. Worlds/memory are disposable. Original incident target was unrecorded; reconstructed cases are not an exact live-world replay.',
 'gym':[], 'conversations':{},'validation':{}, 'drivers':{}, 'source_sha256':{}}
previous=load(root/'docs/plans/13-evidence.json') or {}
e['measured_source_sha256']=previous.get('measured_source_sha256',previous.get('source_sha256',{}))
e['final_review_delta']='Model arms predate the final act(stop) token-forwarding/description fix. No recorded model action supplied a stop token. The final public-tool regression fails before that fix and passes after; full build/vet/test/race/generation was repeated. Final source hashes are separate from measured source hashes.'
for source,runs in [('before',scratch/'base/gym/runs'),('after',root/'gym/runs')]:
    for d in sorted(runs.iterdir()):
        if not (d/'results.json').exists(): continue
        results=load(d/'results.json')
        for run in sorted(d.iterdir()):
            if not run.is_dir() or not (run/'goal.json').exists(): continue
            outcome=load(run/'outcome.json')
            agent=run/'agent.log'
            e['gym'].append({'source':source,'run':str(run),'outcome':outcome,
              'goal':load(run/'goal.json'),'judge':judges(run/'judge.jsonl'),
              'agent_log':agent.read_text() if agent.exists() else None})
        e.setdefault('scoreboards',[]).append({'source':source,'run':str(d),'results':results,
          'scoreboard':(d/'scoreboard.md').read_text() if (d/'scoreboard.md').exists() else None})
for d in sorted(scratch.iterdir()):
    if not d.is_dir() or not (d/'episodes.db').exists(): continue
    db=sqlite3.connect(d/'episodes.db')
    episodes=[dict(zip(['id','at','kind','detail','tokens','cost_usd'],r)) for r in db.execute('select id,at,kind,detail,tokens,cost from episodes order by id')]
    cp=db.execute('select data from checkpoint where id=1').fetchone()
    transcript=[]
    for r in lines(d/'transcript.jsonl'):
        if 'event' in r:
            ev=r['event'];r={'ts':r['ts'],'event':{k:v for k,v in ev.items() if k!='data'}}
        if 'reply_state' in r: r['reply_state']=card(r['reply_state'])
        if 'sample' in r: r['sample']=card(r['sample'])
        if 'partial_gather' in r: r['partial_gather']=card(r['partial_gather'])
        if 'terminal_state' in r: r['terminal_state']=card(r['terminal_state'])
        transcript.append(r)
    e['conversations'][d.name]={'episodes':episodes,'checkpoint':json.loads(cp[0]) if cp else None,
      'judge':judges(d/'judge.jsonl'),'transcript':transcript,
      'serve_log':(d/'serve.log').read_text() if (d/'serve.log').exists() else None,
      'planner_prompt':(d/'planner.md').read_text() if (d/'planner.md').exists() else None}
for p in sorted((scratch/'results').iterdir()):
    if p.suffix=='.log': e['validation'][p.name]=p.read_text()
e['live_stall']={'judge':judges(scratch/'results/live-stall.jsonl'),
 'stops':[r for r in lines(scratch/'results/live-stall.jsonl') if r.get('PASS') or ('elapsed' in r and 'interrupt' in r)]}
for name in ['chat.mjs','travel.mjs','followup.mjs','rcon.go','seed.go','ownership.mjs','terminal.go','live-stall.go','export.py']:
    e['drivers'][name]=(scratch/name).read_text()
changed=subprocess.check_output(['git','diff','--name-only',e['baseline_source']],cwd=root,text=True).splitlines()
changed+=subprocess.check_output(['git','ls-files','--others','--exclude-standard'],cwd=root,text=True).splitlines()
for name in sorted(set(changed)):
    p=root/name
    if p.is_file() and name!='docs/plans/13-evidence.json': e['source_sha256'][name]=digest(p)
sol=sum((r['outcome'] or {}).get('cost_usd',0) for r in e['gym'])
tokens=sum((r['outcome'] or {}).get('tokens',{}).get('total',0) for r in e['gym'])
jev=sum(r['judge']['cost_usd'] for r in e['gym'])+e['live_stall']['judge']['cost_usd']
for c in e['conversations'].values():
    sol+=sum(x['cost_usd'] for x in c['episodes']);tokens+=sum(x['tokens'] for x in c['episodes'])
    jev+=c['judge']['cost_usd']+sum(r['jev_terminal'].get('cost_usd',0) for r in c['transcript'] if 'jev_terminal' in r)
e['returned_usage']={'sol_tokens':tokens,'sol_usd':sol,'jev_usd':jev,'total_usd':sol+jev,
 'cancellation_billing':'Unknown for cancelled/unreturned calls; not a hard invoice cap. Zero returned usage is not proof of no billing.'}
(root/'docs/plans/13-evidence.json').write_text(json.dumps(e,indent=2,ensure_ascii=False)+'\n')
print(json.dumps(e['returned_usage'],indent=2))
print('gym trials',len(e['gym']),'conversations',list(e['conversations']))
